import { readFileSync, writeFileSync } from "node:fs";
// A deterministic generated copy keeps API rootDir/deploy layout stable.
// Browser owns pure wire contracts; this is not handwritten duplicate schema.
const src = "apps/web/shared/api-contract.ts",
  dest = "apps/api/src/contracts.ts";
const expected =
  "// Generated by scripts/sync-contracts.mjs. Edit apps/web/shared/api-contract.ts.\n" +
  readFileSync(src, "utf8");
if (process.argv.includes("--check")) {
  if (readFileSync(dest, "utf8") !== expected)
    throw Error("Shared API contract drift; run npm run contracts:sync");
  console.log("Shared API contract drift check PASS");
} else writeFileSync(dest, expected);
